search:
int searchList(const char *list[], const char *value, int length)
{
    int low = 0, high = length-1, mid = 0;

    while(low <= high)
    {
        mid = (low + high)/2;
        if( stricmp(list[mid], value) < 0 )
        {
            low = mid + 1;
        }
        else if( stricmp(list[mid], value) == 0 )
        {
            return mid;
        }
        else if( stricmp(list[mid], value) > 0 )
        {
            high = mid-1;
        }

    }

    return -1;
}
